"""M2 Stage 2 combined gate runner (single kernel, three sub-gates).

Kaggle script kernels upload ONLY code_file, so K1/K2/K3 are embedded
below by embed_stage2.py before push (same mechanism as Stage 0
embed_dump.py). Locally each gate script is developed and mechanics-tested
separately; the kernel runs all three that fit in one ~50min budget:

  K1 head + transformer x18 (pure python, T<=232, fast).
  K2 conformer x17 full-layer (pure python, T<=60 deep chunks, slower).
  K3 pre_encode stem (pure python convs on mel windows, slowest per frame
      but only 36+224 small windows).

Each gate reads /kaggle/input/diar-m2-ref/*.npz + the .nemo checkpoint
(resolved by the runner: mined from /kaggle/input|working when present,
else downloaded from HF at runtime like Stage 0 S0-c and shared via
M2_STAGE2_CKPT env — the ckpt is NOT in any dataset),
emits its own verdict json to /kaggle/working, and NEVER fails the kernel
on a gate FAIL (a FAIL is data: it measures the spread we pin thresholds
from). Only infra errors (missing ref/ckpt) fail loudly.

Usage locally (mechanics only): python3 kaggle/m2_stage2/embed_stage2.py
"""
from __future__ import annotations

import sys
import time
from pathlib import Path

HERE = Path(__file__).parent
# /kaggle/src is read-only at runtime (v4 ERROR: Errno 30) — materialized
# gates go to a writable dir (same /tmp discipline as Stage 0 TMP).
WORK = Path("/tmp/m2-stage2")
HF_REPO = "nvidia/diar_streaming_sortformer_4spk-v2"
NEMO_FILE = "diar_streaming_sortformer_4spk-v2.nemo"

# Embedded gate sources (filled by embed_stage2.py before push; empty
# string locally). At runtime the runner prefers a sibling file if present
# and otherwise materializes the embedded copy next to itself, then execs
# it as __main__ — mirroring m2_stage0_refdump.py's dump-script fallback.
# Do not hand-edit: embed_stage2.py --check pins embedded == sources.
EMBEDDED_M2_STAGE2_K1 = '"""M2 Stage 2 K1: teacher-forced gates encoder_proj + transformer x18 + head.\n\nReads the Stage 0 .npz reference(s) on the kernel side (dataset, not git),\nruns the numpy-vectorized reference (same math as src/layers.cpp: Linear\n[out,in] @, biased-var LN, contiguous heads, post-LN transformer, relu\nhead), and gates every layer teacher-forced:\n\n  proj gate: conformer_block_16 (512) -> fc_encoder (192) via\n      sortformer_modules.encoder_proj (NeMo frontend_encoder tail).\n  transformer gates: fc_encoder -> transformer_block_00 -> ... ->\n      transformer_block_17 (chain of 18, each fed the REFERENCE predecessor\n      output, never our own — a failure localizes to one block).\n  head gate: transformer_block_17 -> preds_full (forward_speaker_sigmoids).\n\nMetrics per gate: max_abs, mean_abs, cosine, frame_agreement(argmax @0.5).\nThresholds are REPORTED, not pinned here: Stage 2 pins them after first\nmeasurement per plan §1 (fp32-vs-fp32 spread unknown until measured).\n\nLocal mechanics (no torch/NeMo): tests/test_m2_stage2_k1.py checks the\nnumpy helpers against the shipped C++ on synthetic weights (transcription\npins) plus hand-case math; the kernel only adds true-weight .npz I/O.\n"""\nfrom __future__ import annotations\n\nimport json\nimport math\nimport os\nimport subprocess\nimport sys\nimport time\nfrom pathlib import Path\n\n\ndef locate_harness() -> Path:\n    roots = [Path("/kaggle/input"), Path("/kaggle/working")]\n    listing: list[str] = []\n    for root in roots:\n        if not root.exists():\n            continue\n        try:\n            for entry in sorted(root.iterdir()):\n                listing.append(str(entry))\n        except OSError as exc:\n            listing.append(f"{root}: {exc}")\n    for root in roots:\n        if not root.exists():\n            continue\n        for candidate in root.rglob("diar_harness.py"):\n            return candidate.parent\n    raise RuntimeError(\n        "diar_harness.py not found. Kaggle input listing: " + " | ".join(listing)\n    )\n\n\nHARNESS_DIR = locate_harness()\nsys.path.insert(0, str(HARNESS_DIR))\n\nimport diar_harness as h  # noqa: E402\n\nOUT = Path("/kaggle/working")\n\n\ndef find_ckpt() -> Path | None:\n    # Runner shares the resolved/downloaded ckpt via env (see\n    # m2_stage2_run._ensure_ckpt); fall back to dataset/working scan when\n    # a gate runs standalone (local mechanics never reach here).\n    env = os.environ.get("M2_STAGE2_CKPT")\n    if env and Path(env).exists():\n        return Path(env)\n    hits = sorted(Path("/kaggle/input").rglob("*.nemo"))\n    if not hits:\n        hits = sorted(Path("/kaggle/working").rglob("*.nemo"))\n    return hits[0] if hits else None\n\nREPORT: dict[str, object] = {\n    "schema_version": 1,\n    "scope": "pure_speaker_diarization",\n    "job": "m2_stage2_k1_head_transformer",\n}\n\n# ---- numpy-vectorized reference (mirrors src/layers.cpp, torch order) ----\n# NOTE (2026-09-17 perf rewrite): the local mechanics tests pin the C++\n# transcription through these SAME function names on nested lists; the\n# kernel gate path below converts once and runs numpy end to end (~100x:\n# mid 232 frames x 18 blocks drops from ~hours to ~minutes).\n\ndef matvec_rows(x, w, b, t, inn, out):\n    # Legacy helper kept for the mechanics transcription tests (they call it\n    # indirectly? No — kept because test files import nothing else; harmless).\n    # Kernel path never calls this (numpy lin() above). Do NOT delete without\n    # updating tests/test_m2_stage2_k1.py.\n    y = [[0.0] * out for _ in range(t)]\n    for r in range(t):\n        xr = x[r]\n        for o in range(out):\n            acc = b[o] if b is not None else 0.0\n            wr = w[o]\n            for i in range(inn):\n                acc += xr[i] * wr[i]\n            y[r][o] = acc\n    return y\n\n\ndef layernorm(x, g, b, eps=1e-5):\n    y = []\n    for row in x:\n        m = sum(row) / len(row)\n        v = sum((v - m) ** 2 for v in row) / len(row)\n        inv = 1.0 / math.sqrt(v + eps)\n        y.append([(v - m) * inv * (g[i] if g else 1.0) + (b[i] if b else 0.0)\n                  for i, v in enumerate(row)])\n    return y\n\n\ndef softmax_rows(x):\n    y = []\n    for row in x:\n        m = max(row)\n        e = [math.exp(v - m) for v in row]\n        s = sum(e)\n        y.append([v / s for v in e])\n    return y\n\n\ndef transformer_block(x, wt, H=192, I=768, NH=8):\n    import numpy as _np\n    xa = _np.asarray(x, dtype=_np.float64)\n    T = xa.shape[0]\n    DK = H // NH\n\n    def lin(a, w, b):\n        wa = _np.asarray(w, dtype=_np.float64)\n        y = a @ wa.T\n        if b is not None:\n            y = y + _np.asarray(b, dtype=_np.float64)\n        return y\n\n    def ln(a, g, b, eps=1e-5):\n        m = a.mean(axis=1, keepdims=True)\n        v = ((a - m) ** 2).mean(axis=1, keepdims=True)\n        y = (a - m) / _np.sqrt(v + eps)\n        if g is not None:\n            y = y * _np.asarray(g, dtype=_np.float64)\n        if b is not None:\n            y = y + _np.asarray(b, dtype=_np.float64)\n        return y\n\n    q, k, v = lin(xa, wt["q_w"], wt["qb"]), lin(xa, wt["k_w"], wt["kb"]), lin(\n        xa, wt["v_w"], wt["vb"])\n    sc = 1.0 / math.sqrt(DK)\n    # Contiguous head split (matches C++ and torch view(B,T,H,Dk)): head h\n    # owns cols [h*Dk,(h+1)*Dk). Pinned by test_layers head-order cases.\n    heads = []\n    for hd in range(NH):\n        s = (q[:, hd * DK:(hd + 1) * DK] @ k[:, hd * DK:(hd + 1) * DK].T) * sc\n        s = s - s.max(axis=1, keepdims=True)\n        e = _np.exp(s)\n        pr = e / e.sum(axis=1, keepdims=True)\n        heads.append(pr @ v[:, hd * DK:(hd + 1) * DK])\n    attn = _np.concatenate(heads, axis=1)\n    ao = lin(attn, wt["o_w"], wt["ob"])\n    h1 = ln(ao + xa, wt["g1"], wt["b1"])\n    fm = lin(h1, wt["f1_w"], wt["f1_b"])\n    fm = _np.maximum(fm, 0.0)\n    fo = lin(fm, wt["f2_w"], wt["f2_b"])\n    return ln(fo + h1, wt["g2"], wt["b2"]).tolist()\n\n\ndef diar_head(x, hw, hb, sw, sb):\n    import numpy as _np\n    xa = _np.maximum(_np.asarray(x, dtype=_np.float64), 0.0)\n    hwb = _np.asarray(hw, dtype=_np.float64)\n    h1 = _np.maximum(xa @ hwb.T + _np.asarray(hb, dtype=_np.float64), 0.0)\n    swb = _np.asarray(sw, dtype=_np.float64)\n    logits = h1 @ swb.T + _np.asarray(sb, dtype=_np.float64)\n    return (1.0 / (1.0 + _np.exp(-logits))).tolist()\n\n\ndef metrics(ref, got):\n    import numpy as _np\n    r = _np.asarray(ref, dtype=_np.float64)\n    g = _np.asarray(got, dtype=_np.float64)\n    d = np_abs = float(_np.abs(r - g).max())\n    mean = float(_np.abs(r - g).mean())\n    cos = float((r * g).sum() / (math.sqrt((r * r).sum() * (g * g).sum()) + 1e-12))\n    ra = (r > 0.5).astype(int)\n    ga = (g > 0.5).astype(int)\n    agree = float((ra == ga).mean())\n    return {"max_abs": d, "mean_abs": mean, "cosine": cos, "frame_agreement": agree,\n            "ref_rms": float(_np.sqrt((r * r).mean())), "got_rms": float(_np.sqrt((g * g).mean())), "np_abs": np_abs}\n\n\ndef load_nemo_state_dict(ckpt_path):\n    import tarfile, io\n    import torch\n    sd = None\n    with tarfile.open(ckpt_path, "r") as tf:\n        for m in tf.getmembers():\n            if m.name.endswith(".ckpt"):\n                f = tf.extractfile(m)\n                obj = torch.load(io.BytesIO(f.read()), map_location="cpu", weights_only=False)\n                sd = obj.get("state_dict", obj)\n                break\n    assert sd is not None, "no .ckpt in .nemo"\n    return sd\n\n\ndef t2(w):\n    # torch Linear weight [out,in] -> nested lists, SAME layout (NO transpose).\n    # The python mirrors index w[o][i] (row o = output unit), exactly like\n    # nn::linear_forward. Transposing here silently corrupts square weights\n    # and crashes on rectangular ones — pinned by test_t2_keeps_torch_layout.\n    import numpy as _np\n    a = _np.asarray(w.detach().cpu().numpy() if hasattr(w, "detach") else w, dtype=_np.float64)\n    return a.tolist()\n\n\ndef v1(w):\n    import numpy as _np\n    return _np.asarray(w.detach().cpu().numpy() if hasattr(w, "detach") else w,\n                       dtype=_np.float64).ravel().tolist()\n\n\ndef main() -> int:\n    import numpy as _np\n    REPORT["environment"] = h.environment_record()\n    REPORT["gpu_before"] = h.gpu_snapshot()\n\n    ref_dir = None\n    for cand in (Path("/kaggle/input"), Path("/kaggle/working")):\n        hits = sorted(cand.rglob("m2_ref_short.npz"))\n        if hits:\n            ref_dir = hits[0].parent\n            break\n    if ref_dir is None:\n        REPORT["verdict"] = "ref-missing"\n        REPORT["finished_utc"] = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())\n        h.emit_report(REPORT, name="m2_stage2_k1_verdict.json")\n        return 0\n    ckpts = sorted(Path("/kaggle/input").rglob("*.nemo"))\n    if not ckpts:\n        ckpts = sorted(Path("/kaggle/working").rglob("*.nemo"))\n    env_ckpt = os.environ.get("M2_STAGE2_CKPT")\n    if env_ckpt and Path(env_ckpt).exists():\n        ckpts = [Path(env_ckpt)]\n    if not ckpts:\n        REPORT["verdict"] = "ckpt-missing"\n        REPORT["note"] = ("no .nemo in /kaggle/input|working and no "\n                          "M2_STAGE2_CKPT from the runner (download failed?)")\n        REPORT["finished_utc"] = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())\n        h.emit_report(REPORT, name="m2_stage2_k1_verdict.json")\n        return 0\n    REPORT["ref_dir"] = str(ref_dir)\n    REPORT["ckpt"] = str(ckpts[0])\n\n    sd = load_nemo_state_dict(str(ckpts[0]))\n\n    def G(name):\n        for cand in (name, "transformer_encoder." + name):\n            if cand in sd:\n                return sd[cand]\n        raise KeyError(name)\n\n    # Per-block transformer weights: NeMo TransformerEncoder layers[i].\n    n_blocks = 18\n    blocks = []\n    for bi in range(n_blocks):\n        p = f"transformer_encoder.layers.{bi}."\n        blocks.append({\n            "q_w": t2(sd[p + "first_sub_layer.query_net.weight"]),\n            "qb": v1(sd[p + "first_sub_layer.query_net.bias"]),\n            "k_w": t2(sd[p + "first_sub_layer.key_net.weight"]),\n            "kb": v1(sd[p + "first_sub_layer.key_net.bias"]),\n            "v_w": t2(sd[p + "first_sub_layer.value_net.weight"]),\n            "vb": v1(sd[p + "first_sub_layer.value_net.bias"]),\n            "o_w": t2(sd[p + "first_sub_layer.out_projection.weight"]),\n            "ob": v1(sd[p + "first_sub_layer.out_projection.bias"]),\n            "g1": v1(sd[p + "layer_norm_1.weight"]),\n            "b1": v1(sd[p + "layer_norm_1.bias"]),\n            "g2": v1(sd[p + "layer_norm_2.weight"]),\n            "b2": v1(sd[p + "layer_norm_2.bias"]),\n            "f1_w": t2(sd[p + "second_sub_layer.dense_in.weight"]),\n            "f1_b": v1(sd[p + "second_sub_layer.dense_in.bias"]),\n            "f2_w": t2(sd[p + "second_sub_layer.dense_out.weight"]),\n            "f2_b": v1(sd[p + "second_sub_layer.dense_out.bias"]),\n        })\n    # Head weights live on sortformer_modules.\n    def H(name):\n        if name in sd:\n            return sd[name]\n        raise KeyError(name)\n    hw = t2(H("sortformer_modules.first_hidden_to_hidden.weight"))\n    hb = v1(H("sortformer_modules.first_hidden_to_hidden.bias"))\n    sw = t2(H("sortformer_modules.single_hidden_to_spks.weight"))\n    sb = v1(H("sortformer_modules.single_hidden_to_spks.bias"))\n    # encoder_proj (fc 512 -> transformer 192): NeMo SortformerModules\n    # attribute `encoder_proj` (sortformer_model.cpp: encoder_proj_).\n    proj_w = t2(sd["sortformer_modules.encoder_proj.weight"])\n    proj_b = v1(sd["sortformer_modules.encoder_proj.bias"])\n    REPORT["encoder_proj_shape"] = [len(proj_w), len(proj_w[0])]\n\n    per_audio = {}\n    for label in ("short", "mid"):\n        zpath = ref_dir / f"m2_ref_{label}.npz"\n        if not zpath.exists():\n            continue\n        z = _np.load(str(zpath), allow_pickle=True)\n        deep = [k.split("/")[0] for k in z.files if k.endswith("conformer_block_00")]\n        audio_gates = {"head": [], "blocks": [], "proj": []}\n        for chunk in deep:\n            # encoder_proj gate: conformer_block_16 (512) -> fc_encoder\n            # (192). frontend_encoder = encoder(...) + transpose + proj\n            # (NeMo SortformerEncLabelModel.frontend_encoder).\n            c16 = z[chunk + "/conformer_block_16"].tolist()\n            fc_ref = z[chunk + "/fc_encoder"].tolist()\n            import numpy as _np2\n            pw_ = _np2.asarray(proj_w, dtype=_np2.float64)\n            fc_got = (_np2.asarray(c16, dtype=_np2.float64) @ pw_.T\n                      + _np2.asarray(proj_b, dtype=_np2.float64)[None, :]).tolist()\n            m = metrics(fc_ref, fc_got)\n            m.update({"chunk": chunk})\n            audio_gates["proj"].append(m)\n            fc = fc_ref  # transformer chain eats the REFERENCE fc input\n            # 18 teacher-forced block gates.\n            prev = fc\n            for bi in range(n_blocks):\n                got = transformer_block(prev, blocks[bi])\n                ref = z[chunk + f"/transformer_block_{bi:02d}"].tolist()\n                m = metrics(ref, got)\n                m.update({"chunk": chunk, "block": bi})\n                audio_gates["blocks"].append(m)\n                prev = ref  # teacher forcing: next block eats REFERENCE\n            # Head gate eats reference block-17 output.\n            t17 = z[chunk + "/transformer_block_17"].tolist()\n            preds = diar_head(t17, hw, hb, sw, sb)\n            ref_preds = z[chunk + "/preds_full"].tolist()\n            # forward_infer multiplies by output_mask (all ones here: full\n            # length, no padding) — direct compare valid.\n            m = metrics(ref_preds, preds)\n            m.update({"chunk": chunk})\n            audio_gates["head"].append(m)\n        per_audio[label] = audio_gates\n\n    REPORT["gates"] = per_audio\n    worst_block = max((m["max_abs"] for a in per_audio.values() for m in a["blocks"]),\n                      default=float("nan"))\n    worst_head = max((m["max_abs"] for a in per_audio.values() for m in a["head"]),\n                     default=float("nan"))\n    worst_proj = max((m["max_abs"] for a in per_audio.values() for m in a["proj"]),\n                     default=float("nan"))\n    REPORT["worst_block_max_abs"] = worst_block\n    REPORT["worst_head_max_abs"] = worst_head\n    REPORT["worst_proj_max_abs"] = worst_proj\n    REPORT["verdict"] = "k1-measured"\n    REPORT["note"] = ("teacher-forced fp32-vs-fp32 spreads measured; "\n                      "pin gate thresholds from these numbers per plan §1.")\n    REPORT["gpu_after"] = h.gpu_snapshot()\n    REPORT["finished_utc"] = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())\n    h.emit_report(REPORT, name="m2_stage2_k1_verdict.json")\n    print(json.dumps({k: v for k, v in REPORT.items() if k != "gates"}, indent=1)[:2000])\n    return 0\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'
EMBEDDED_M2_STAGE2_K2 = '"""M2 Stage 2 K2: teacher-forced gates conformer conv + FF + full layer x17.\n\nSame harness pattern as K1 (pure-python reference mirrored from\nsrc/conv.cpp + src/layers.cpp + src/conformer.cpp; local mechanics tests\npin the python-vs-C++ transcription). Kernel-side: load .nemo state dict,\nbuild per-layer weights, and gate teacher-forced on deep chunks:\n\n  conv gate:  norm_conv(conformer input) -> conv module -> compare vs a\n      locally recomputed reference is NOT available (no intermediate dump),\n      so the conv gate runs INSIDE the full-layer gate: the full layer is\n      computed with reference submodule inputs at each stage? No — without\n      per-submodule dumps only the full-layer boundary is gateable. The K2\n      verdict therefore gates full conformer_layer_00..16 (input =\n      reference predecessor block output; layer 00 input = xscaled concat\n      [spkcache|fifo|pre_encode] reconstructed from state_lens_before +\n      fifo_after/spkcache_after? No — chunk000 has empty state, so layer-00\n      input = xscale(pre_encode) + pos table; later chunks need state which\n      IS in the dump (fifo_after/spkcache_after of the PREVIOUS chunk).\n\n  Practical K2 gate set (no new dump needed):\n  - layer00/chunk000..002: input = concat([], [], pre_encode) xscaled;\n    pos table built locally (posenc formula, pinned by test_posenc).\n  - layerNN/chunk000..002: input = reference conformer_block_{NN-1}\n    (teacher forcing through the stack).\n  - FF/conv submodule gates: synthetic-weight python-vs-C++ already green\n    locally; true-weight submodule isolation is impossible without new\n    dumps, so a full-layer FAIL localizes by re-running the layer with\n    reference NORM outputs? Also unavailable. Localization fallback: swap\n    in reference MHA-vs-local per K1-style recompute is possible because\n    MHA inputs ARE reproducible (normed input). The kernel therefore ALSO\n    reports per-stage recompute metrics (norm+MHA vs reference? no\n    reference). Honest scope: K2 gates FULL layers; submodule truth waits\n    for Stage 3 free-running assembly. A K2 FAIL triages by which layer\n    index and which chunk length first diverges (length-dependent =\n    pos-table/shift suspect; layer-0-only = xscale/concat suspect).\n\nVerdict: K2-measured with worst_layer_max_abs. Thresholds pinned after.\n"""\nfrom __future__ import annotations\n\nimport math\nimport os\nimport sys\nimport time\nfrom pathlib import Path\n\n\ndef locate_harness() -> Path:\n    roots = [Path("/kaggle/input"), Path("/kaggle/working")]\n    for root in roots:\n        if not root.exists():\n            continue\n        for candidate in root.rglob("diar_harness.py"):\n            return candidate.parent\n    raise RuntimeError("diar_harness.py not found")\n\n\nHARNESS_DIR = locate_harness()\nsys.path.insert(0, str(HARNESS_DIR))\n\nimport diar_harness as h  # noqa: E402\n\nOUT = Path("/kaggle/working")\n\n\ndef find_ckpt() -> Path | None:\n    # Runner shares the resolved/downloaded ckpt via env (see\n    # m2_stage2_run._ensure_ckpt); fall back to dataset/working scan when\n    # a gate runs standalone (local mechanics never reach here).\n    env = os.environ.get("M2_STAGE2_CKPT")\n    if env and Path(env).exists():\n        return Path(env)\n    hits = sorted(Path("/kaggle/input").rglob("*.nemo"))\n    if not hits:\n        hits = sorted(Path("/kaggle/working").rglob("*.nemo"))\n    return hits[0] if hits else None\nREPORT: dict[str, object] = {\n    "schema_version": 1,\n    "scope": "pure_speaker_diarization",\n    "job": "m2_stage2_k2_conformer",\n}\n\nD_MODEL, D_FF, N_HEADS, KERNEL = 512, 2048, 8, 9\n# pos_bias_u/v are SHARED across all conformer layers (single nn.Parameter on\n# the encoder, passed by reference into each ConformerLayer — see NeMo\n# ConformerEncoder.__init__ `if not untie_biases` branch; diar keeps the\n# default untie_biases=True... which takes the SHARED branch: the `if not`\n# is True, one (n_heads, d_head) pair is created and handed to every layer).\n# NeMo key names (state dict of the .nemo): the shared pair lives at\n# encoder.pos_bias_u / encoder.pos_bias_v (encoder-level, NO layer index);\n# per-layer projections are encoder.layers.{li}.self_attn.linear_{q,k,v,pos,out}.*.\nPOS_BIAS_U_KEY = "encoder.pos_bias_u"\nPOS_BIAS_V_KEY = "encoder.pos_bias_v"\n\n\ndef layer_prefix(li):\n    return f"encoder.layers.{li}."\n\n\ndef matvec_rows(x, w, b, t, inn, out):\n    # Legacy helper retained for the mechanics transcription tests only;\n    # the kernel path uses lin_np/layernorm_np (numpy). See K1 header note.\n    y = [[0.0] * out for _ in range(t)]\n    for r in range(t):\n        xr = x[r]\n        for o in range(out):\n            acc = b[o] if b is not None else 0.0\n            wr = w[o]\n            for i in range(inn):\n                acc += xr[i] * wr[i]\n            y[r][o] = acc\n    return y\n\n\ndef layernorm(x, g, b, eps=1e-5):\n    y = []\n    for row in x:\n        m = sum(row) / len(row)\n        v = sum((v - m) ** 2 for v in row) / len(row)\n        inv = 1.0 / math.sqrt(v + eps)\n        y.append([(v - m) * inv * (g[i] if g else 1.0) + (b[i] if b else 0.0)\n                  for i, v in enumerate(row)])\n    return y\n\n\ndef softmax_rows(x):\n    # Legacy helper retained for the mechanics tests only (test files\n    # reference nothing else by this name; harmless). Kernel path uses\n    # inline numpy softmax. Do NOT delete without updating tests.\n    y = []\n    for row in x:\n        m = max(row)\n        e = [math.exp(v - m) for v in row]\n        s = sum(e)\n        y.append([v / s for v in e])\n    return y\n\n\ndef relpos_table(L, D):\n    div = [math.exp(i * -(math.log(10000.0) / D)) for i in range(D // 2)]\n    pe = []\n    for r in range(2 * L - 1):\n        pos = (L - 1) - r\n        row = []\n        for i in range(D // 2):\n            row += [math.sin(pos * div[i]), math.cos(pos * div[i])]\n        pe.append(row)\n    return pe\n\n\ndef shift_torch(bd, T):\n    # bd[P][T] (rows relpos, cols query); S[q][k] = bd[k-q+T-1][q].\n    P = 2 * T - 1\n    return [[bd[k - q + T - 1][q] for k in range(T)] for q in range(T)]\n\n\ndef relpos_mha(x, pe, wt, C, NH):\n    # Numpy-vectorized (same perf rewrite as K1): identical math to the C++\n    # (contiguous heads, query-major shift S[q,k]=bd[k-q+T-1][q], plain\n    # sqrt(Dk) scale, merge, linear_out). Nested-list I/O for the mechanics\n    # tests; the kernel gate converts once outside the layer loop.\n    import numpy as _np\n    xa = _np.asarray(x, dtype=_np.float64)\n    pa = _np.asarray(pe, dtype=_np.float64)\n    T = xa.shape[0]\n    DK = C // NH\n\n    def lin(a, w, b):\n        y = a @ _np.asarray(w, dtype=_np.float64).T\n        return y if b is None else y + _np.asarray(b, dtype=_np.float64)\n\n    q, k, v = lin(xa, wt["q_w"], wt["qb"]), lin(xa, wt["k_w"], wt["kb"]), lin(\n        xa, wt["v_w"], wt["vb"])\n    p = lin(pa, wt["pos_w"], None)\n    # NeMo pos_bias_{u,v} are (H, Dk); the kernel stores them via v1()\n    # (raveled [C], head-contiguous) and slices flat per head below — same\n    # convention as the C++ (reshape(d_k,1,n_head,1) over the same bytes).\n    # A transposed future checkpoint fails LOUDLY on the size assert.\n    bu = _np.asarray(wt["bu"], dtype=_np.float64).ravel()\n    bv = _np.asarray(wt["bv"], dtype=_np.float64).ravel()\n    assert bu.size == C and bv.size == C, (bu.shape, bv.shape, C)\n    sdk = math.sqrt(DK)\n    heads = []\n    for hd in range(NH):\n        s = slice(hd * DK, (hd + 1) * DK)\n        # bd[q, r] = (q[q]+bv) . p[r] over head dims; S[q,k] = bd[q, k-q+T-1].\n        # bd here is [T, P] query-major — the TRANSPOSE of the old nested-list\n        # bd[P][T] that shift_torch consumes. The identity-trace proof still\n        # holds: S[q,k] = (q[q]+bv).p[k-q+T-1] either way; only the storage\n        # orientation changed with the numpy rewrite.\n        bd = (q[:, s] + bv[s]) @ p[:, s].T  # [T, P]\n        P = 2 * T - 1\n        sh = _np.stack([bd[_np.arange(T), k - _np.arange(T) + T - 1] for k in range(T)],\n                       axis=1)  # S[q,k] = bd[q, k-q+T-1]\n        ac = (q[:, s] + bu[s]) @ k[:, s].T  # [T, T]\n        sc = (ac + sh) / sdk\n        sc = sc - sc.max(axis=1, keepdims=True)\n        e = _np.exp(sc)\n        pr = e / e.sum(axis=1, keepdims=True)\n        heads.append(pr @ v[:, s])\n    merged = _np.concatenate(heads, axis=1)\n    return lin(merged, wt["o_w"], wt["ob"]).tolist()\n\n\ndef conformer_ff(x, w1, b1, w2, b2):\n    import numpy as _np\n    xa = _np.asarray(x, dtype=_np.float64)\n    mid = xa @ _np.asarray(w1, dtype=_np.float64).T + _np.asarray(b1, dtype=_np.float64)\n    act = mid / (1.0 + _np.exp(-mid))  # SiLU == Swish\n    return (act @ _np.asarray(w2, dtype=_np.float64).T + _np.asarray(\n        b2, dtype=_np.float64)).tolist()\n\n\ndef layernorm_np(xa, g, b, eps=1e-5):\n    import numpy as _np\n    m = xa.mean(axis=1, keepdims=True)\n    v = ((xa - m) ** 2).mean(axis=1, keepdims=True)\n    y = (xa - m) / _np.sqrt(v + eps)\n    if g is not None:\n        y = y * _np.asarray(g, dtype=_np.float64)\n    if b is not None:\n        y = y + _np.asarray(b, dtype=_np.float64)\n    return y\n\n\ndef lin_np(xa, w, b):\n    import numpy as _np\n    y = xa @ _np.asarray(w, dtype=_np.float64).T\n    return y if b is None else y + _np.asarray(b, dtype=_np.float64)\n\n\ndef conformer_conv(x, wt, D, K=9):\n    import numpy as _np\n    xa = _np.asarray(x, dtype=_np.float64)\n    T = xa.shape[0]\n    e = lin_np(xa, wt["pw1_w"], wt["pw1_b"])  # [T, 2D]\n    a, b = e[:, :D], e[:, D:]\n    g = a / (1.0 + _np.exp(-b))  # GLU, a = FIRST half (see K1 header note)\n    # Depthwise k, symmetric pad == offline CausalConv1D full context.\n    pad = (K - 1) // 2\n    gp = _np.pad(g, ((pad, pad), (0, 0)))\n    dww = _np.asarray(wt["dw_w"], dtype=_np.float64)  # [D, K]\n    # gp[idx]: [T, K, D] window stack; einsum over taps -> [T, D].\n    idx = _np.arange(T)[:, None] + _np.arange(K)[None, :]\n    dw = _np.einsum("tkd,dk->td", gp[idx], dww) \\\n        + _np.asarray(wt["dw_b"], dtype=_np.float64)[None, :]\n    mean = _np.asarray(wt["mean"], dtype=_np.float64)[None, :]\n    var = _np.asarray(wt["var"], dtype=_np.float64)[None, :]\n    n = ((dw - mean) / _np.sqrt(var + 1e-5) * _np.asarray(wt["bn_w"], dtype=_np.float64)[None, :]\n         + _np.asarray(wt["bn_b"], dtype=_np.float64)[None, :])\n    act = n / (1.0 + _np.exp(-n))  # Swish == SiLU\n    return lin_np(act, wt["pw2_w"], wt["pw2_b"]).tolist()\n\n\ndef conformer_layer(x, pe, wt, D, F, NH, K=9):\n    import numpy as _np\n    res = _np.asarray(x, dtype=_np.float64)\n    pea = _np.asarray(pe, dtype=_np.float64)\n    f1 = _np.asarray(conformer_ff(\n        layernorm_np(res, wt["g1"], wt["b1"]).tolist(),\n        wt["w1"], wt["bb1"], wt["w2"], wt["bb2"]), dtype=_np.float64)\n    res = res + 0.5 * f1\n    at = _np.asarray(relpos_mha(\n        layernorm_np(res, wt["ga"], wt["ba"]).tolist(), pea.tolist(),\n        wt["attn"], D, NH), dtype=_np.float64)\n    res = res + at\n    cv = _np.asarray(conformer_conv(\n        layernorm_np(res, wt["gc"], wt["bc"]).tolist(), wt["conv"], D, K),\n        dtype=_np.float64)\n    res = res + cv\n    f2 = _np.asarray(conformer_ff(\n        layernorm_np(res, wt["g2"], wt["b2"]).tolist(),\n        wt["w3"], wt["bb3"], wt["w4"], wt["bb4"]), dtype=_np.float64)\n    res = res + 0.5 * f2\n    return layernorm_np(res, wt["go"], wt["bo"]).tolist()\n\n\ndef metrics(ref, got):\n    import numpy as _np\n    r = _np.asarray(ref, dtype=_np.float64)\n    g = _np.asarray(got, dtype=_np.float64)\n    ra = (r > 0.5).astype(int)\n    ga = (g > 0.5).astype(int)\n    return {"max_abs": float(_np.abs(r - g).max()), "mean_abs": float(_np.abs(r - g).mean()),\n            "cosine": float((r * g).sum() / (math.sqrt((r * r).sum() * (g * g).sum()) + 1e-12)),\n            "frame_agreement": float((ra == ga).mean()),\n            "ref_rms": float(_np.sqrt((r * r).mean())),\n            "got_rms": float(_np.sqrt((g * g).mean()))}\n\n\ndef load_sd(ckpt_path):\n    import tarfile, io\n    import torch\n    with tarfile.open(ckpt_path, "r") as tf:\n        for m in tf.getmembers():\n            if m.name.endswith(".ckpt"):\n                f = tf.extractfile(m)\n                obj = torch.load(io.BytesIO(f.read()), map_location="cpu", weights_only=False)\n                return obj.get("state_dict", obj)\n    raise RuntimeError("no .ckpt in .nemo")\n\n\ndef t2(w):\n    # torch Linear weight [out,in] -> nested lists, SAME layout (NO transpose).\n    # Python mirrors + C++ nn::linear_forward both index w[o][i]; a transpose\n    # here is a silent corruption (square) or shape crash (rectangular) —\n    # pinned by test_t2_keeps_torch_layout below.\n    import numpy as _np\n    a = _np.asarray(w.detach().cpu().numpy() if hasattr(w, "detach") else w, dtype=_np.float64)\n    return a.tolist()\n\n\ndef v1(w):\n    import numpy as _np\n    return _np.asarray(w.detach().cpu().numpy() if hasattr(w, "detach") else w,\n                       dtype=_np.float64).ravel().tolist()\n\n\ndef main() -> int:\n    import numpy as _np\n    import json\n    REPORT["environment"] = h.environment_record()\n    REPORT["gpu_before"] = h.gpu_snapshot()\n    ref_hits = sorted(Path("/kaggle/input").rglob("m2_ref_short.npz")) or \\\n        sorted(Path("/kaggle/working").rglob("m2_ref_short.npz"))\n    ckpts = sorted(Path("/kaggle/input").rglob("*.nemo")) or \\\n        sorted(Path("/kaggle/working").rglob("*.nemo"))\n    env_ckpt = os.environ.get("M2_STAGE2_CKPT")\n    if env_ckpt and Path(env_ckpt).exists():\n        ckpts = [Path(env_ckpt)]\n    if not ref_hits or not ckpts:\n        REPORT["verdict"] = "ref-or-ckpt-missing"\n        REPORT["finished_utc"] = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())\n        h.emit_report(REPORT, name="m2_stage2_k2_verdict.json")\n        return 0\n    ref_dir = ref_hits[0].parent\n    REPORT["ref_dir"] = str(ref_dir)\n    REPORT["ckpt"] = str(ckpts[0])\n    sd = load_sd(str(ckpts[0]))\n\n    def resolve_bias(key):\n        # Shared encoder-level pair; fall back to per-layer copies if a\n        # future checkpoint unties them (same (H,Dk) shape either way).\n        if key in sd:\n            return v1(sd[key])\n        per_layer = [v1(sd[layer_prefix(li) + "self_attn." + key.split(".")[-1]])\n                     for li in range(17)\n                     if layer_prefix(li) + "self_attn." + key.split(".")[-1] in sd]\n        if per_layer:\n            REPORT.setdefault("pos_bias_untied", True)\n            return per_layer[0]\n        raise KeyError(key)\n\n    bu_shared = resolve_bias(POS_BIAS_U_KEY)\n    bv_shared = resolve_bias(POS_BIAS_V_KEY)\n    REPORT["pos_bias_source"] = ("shared:" + POS_BIAS_U_KEY if POS_BIAS_U_KEY in sd\n                                 else "per-layer-fallback")\n\n    layers = []\n    for li in range(17):\n        p = f"encoder.layers.{li}."\n        # NeMo ConformerLayer submodule names (conformer_modules.py):\n        #   norm_feed_forward1/feed_forward1(linear1/linear2) +\n        #   norm_self_att/self_attn(linear_q/k/v/pos/out, pos_bias_u/v shared) +\n        #   norm_conv/conv(pointwise_conv1/depthwise_conv/batch_norm/pointwise_conv2) +\n        #   norm_feed_forward2/feed_forward2 + norm_out.\n        # Full key list per layer (resolved against ckpt at runtime):\n        #   {p}norm_feed_forward1.weight/bias, {p}feed_forward1.linear1/2.weight/bias,\n        #   {p}norm_self_att.*, {p}self_attn.linear_q/k/v/pos/out.*,\n        #   {p}norm_conv.*, {p}conv.pointwise_conv1/depthwise_conv/batch_norm/pointwise_conv2.*,\n        #   {p}norm_feed_forward2.*, {p}feed_forward2.*, {p}norm_out.*.\n        attn = {"q_w": t2(sd[p + "self_attn.linear_q.weight"]),\n                "qb": v1(sd[p + "self_attn.linear_q.bias"]),\n                "k_w": t2(sd[p + "self_attn.linear_k.weight"]),\n                "kb": v1(sd[p + "self_attn.linear_k.bias"]),\n                "v_w": t2(sd[p + "self_attn.linear_v.weight"]),\n                "vb": v1(sd[p + "self_attn.linear_v.bias"]),\n                "pos_w": t2(sd[p + "self_attn.linear_pos.weight"]),\n                "bu": bu_shared,  # shared encoder pair (see POS_BIAS_*_KEY)\n                "bv": bv_shared,  # (same values for every layer)\n                "o_w": t2(sd[p + "self_attn.linear_out.weight"]),\n                "ob": v1(sd[p + "self_attn.linear_out.bias"])}\n        # FF norms + bodies (ConformerFeedForward.linear1/linear2).\n        ff1 = {"w1": t2(sd[p + "feed_forward1.linear1.weight"]),\n               "bb1": v1(sd[p + "feed_forward1.linear1.bias"]),\n               "w2": t2(sd[p + "feed_forward1.linear2.weight"]),\n               "bb2": v1(sd[p + "feed_forward1.linear2.bias"])}\n        ff2 = {"w1": t2(sd[p + "feed_forward2.linear1.weight"]),\n               "bb1": v1(sd[p + "feed_forward2.linear1.bias"]),\n               "w2": t2(sd[p + "feed_forward2.linear2.weight"]),\n               "bb2": v1(sd[p + "feed_forward2.linear2.bias"])}\n        norms = {"g1": v1(sd[p + "norm_feed_forward1.weight"]),\n                 "b1": v1(sd[p + "norm_feed_forward1.bias"]),\n                 "ga": v1(sd[p + "norm_self_att.weight"]),\n                 "ba": v1(sd[p + "norm_self_att.bias"]),\n                 "gc": v1(sd[p + "norm_conv.weight"]),\n                 "bc": v1(sd[p + "norm_conv.bias"]),\n                 "g2": v1(sd[p + "norm_feed_forward2.weight"]),\n                 "b2": v1(sd[p + "norm_feed_forward2.bias"]),\n                 "go": v1(sd[p + "norm_out.weight"]),\n                 "bo": v1(sd[p + "norm_out.bias"])}\n        # Conv module (ConformerConvolution, batch_norm flavour). Torch Conv1d\n        # weights are 3D: pointwise [out,in,1] -> squeeze trailing dim to\n        # [out,in]; depthwise [D,1,K] -> squeeze dim-1 to [D,K] (groups=D).\n        # Depthwise dim fork (see conformer_conv docstring): [D,K] expected;\n        # a [2D,K] checkpoint would mean the \'glu_\' registry branch — report\n        # LOUDLY via verdict below, never silently reshape.\n        _dw = _np.asarray(sd[p + "conv.depthwise_conv.weight"])\n        REPORT.setdefault("dw_shape_" + str(li), list(_dw.shape))\n        _pw1 = t2(sd[p + "conv.pointwise_conv1.weight"])\n        _pw2 = t2(sd[p + "conv.pointwise_conv2.weight"])\n        _dwl = t2(sd[p + "conv.depthwise_conv.weight"])\n        pw1_w = [[v[0] for v in row] for row in _pw1]  # [2D,D,1] -> [2D,D]\n        pw2_w = [[v[0] for v in row] for row in _pw2]  # [D,D,1] -> [D,D]\n        dw_w = [ch[0] for ch in _dwl]  # [D,1,K] -> [D,K]\n        conv = {"pw1_w": pw1_w,\n                "pw1_b": v1(sd[p + "conv.pointwise_conv1.bias"]),\n                "dw_w": dw_w,\n                "dw_b": v1(sd[p + "conv.depthwise_conv.bias"]),\n                "bn_w": v1(sd[p + "conv.batch_norm.weight"]),\n                "bn_b": v1(sd[p + "conv.batch_norm.bias"]),\n                "mean": v1(sd[p + "conv.batch_norm.running_mean"]),\n                "var": v1(sd[p + "conv.batch_norm.running_var"]),\n                "pw2_w": pw2_w,\n                "pw2_b": v1(sd[p + "conv.pointwise_conv2.bias"])}\n        layers.append({"attn": attn, "ff1": ff1, "ff2": ff2, "norms": norms, "conv": conv})\n    # Concat->xscale->pos-table input for layer 00 comes from the reference\n    # dump itself (no new dump needed): chunk000 has empty streaming state,\n    # so layer-00 input = xscale(pre_encode); later layers teacher-force on\n    # reference conformer_block_{NN-1}. The pos_emb table is the analytic\n    # NeMo RelPositionalEncoding window (relpos_table, pinned by test_posenc).\n    xs = math.sqrt(D_MODEL)\n    per_audio = {}\n    for label in ("short", "mid"):\n        zpath = ref_dir / f"m2_ref_{label}.npz"\n        if not zpath.exists():\n            continue\n        z = _np.load(str(zpath), allow_pickle=True)\n        deep = [k.split("/")[0] for k in z.files if k.endswith("conformer_block_00")]\n        gates = []\n        for chunk in deep:\n            L = int(z[chunk + "/pre_encode"].shape[0])  # == layer-00 T for chunk000\n            # Layer-00 full-length input: concat([], [], pre_encode) xscaled.\n            # For chunks >000 the reference fc path already includes fifo/\n            # spkcache accumulation, so teacher-force through the stack on\n            # the FULL fc length: layer li eats reference block li-1, and\n            # layer 00 eats the reference fc input? No — fc ENCODER output\n            # is the stack OUTPUT. Reconstruct layer-00 input as\n            # xscale(concat(prev_fifo, prev_pre, pre)) from *_after of the\n            # previous chunk (state_lens_before gives the split points).\n            prev_idx = int(chunk.replace("chunk", "")) - 1\n            if prev_idx < 0:\n                l00_in = [[v * xs for v in row]\n                          for row in z[chunk + "/pre_encode"].tolist()]\n                T = L\n            else:\n                prev = f"chunk{prev_idx:03d}/"\n                n_spk, n_fifo, n_pre = (int(v) for v in z[chunk + "/state_lens_before"])\n                parts = []\n                if n_spk:\n                    parts += z[prev + "spkcache_after"].tolist()[-n_spk:]\n                if n_fifo:\n                    parts += z[prev + "fifo_after"].tolist()[-n_fifo:]\n                parts += z[chunk + "/pre_encode"].tolist()\n                assert len(parts) == n_spk + n_fifo + n_pre, (chunk, len(parts))\n                l00_in = [[v * xs for v in row] for row in parts]\n                T = len(l00_in)\n            pe = relpos_table(T, D_MODEL)\n            prev_out = l00_in\n            for li in range(17):\n                wt = {"g1": layers[li]["norms"]["g1"], "b1": layers[li]["norms"]["b1"],\n                      "w1": layers[li]["ff1"]["w1"], "bb1": layers[li]["ff1"]["bb1"],\n                      "w2": layers[li]["ff1"]["w2"], "bb2": layers[li]["ff1"]["bb2"],\n                      "ga": layers[li]["norms"]["ga"], "ba": layers[li]["norms"]["ba"],\n                      "attn": layers[li]["attn"],\n                      "gc": layers[li]["norms"]["gc"], "bc": layers[li]["norms"]["bc"],\n                      "conv": layers[li]["conv"],\n                      "g2": layers[li]["norms"]["g2"], "b2": layers[li]["norms"]["b2"],\n                      "w3": layers[li]["ff2"]["w1"], "bb3": layers[li]["ff2"]["bb1"],\n                      "w4": layers[li]["ff2"]["w2"], "bb4": layers[li]["ff2"]["bb2"],\n                      "go": layers[li]["norms"]["go"], "bo": layers[li]["norms"]["bo"]}\n                got = conformer_layer(prev_out, pe, wt, D_MODEL, D_FF, N_HEADS, KERNEL)\n                ref = z[chunk + f"/conformer_block_{li:02d}"].tolist()\n                m = metrics(ref, got)\n                m.update({"chunk": chunk, "layer": li, "T": T})\n                gates.append(m)\n                prev_out = ref  # teacher forcing through the stack\n        per_audio[label] = gates\n    REPORT["gates"] = per_audio\n    worst = max((m["max_abs"] for gates in per_audio.values() for m in gates),\n                default=float("nan"))\n    REPORT["worst_layer_max_abs"] = worst\n    REPORT["verdict"] = "k2-measured"\n    REPORT["note"] = ("17-layer teacher-forced fp32-vs-fp32 spreads; "\n                      "pin gate thresholds from these numbers per plan §1.")\n    REPORT["finished_utc"] = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())\n    h.emit_report(REPORT, name="m2_stage2_k2_verdict.json")\n    print(json.dumps({k: v for k, v in REPORT.items() if k != "gates"}, indent=1)[:2000])\n    return 0\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'
EMBEDDED_M2_STAGE2_K3 = '"""M2 Stage 2 K3: teacher-forced gate pre_encode stem (mel_window -> pre_encode).\n\nNumpy-vectorized mirror of src/subsampling.cpp (mechanics tests pin the\ntranscription through the SAME helpers the kernel calls: conv2d/dw/pw/\nflat_cf/lin below now take/return nested lists but compute in numpy —\nidentical values, ~50x faster than the old triple loops; a 160x128 mel\nwindow drops from ~60s to ~1s, so the full 260-chunk gate fits the kernel\nbudget). Kernel-side: weights from the .nemo state dict\n(encoder.pre_encode.conv.* + encoder.pre_encode.out.*), gate on every chunk\n(all 36 short + all 224 mid).\n\nVerdict: K3-measured with worst_max_abs. Thresholds pinned after.\ndw_striding index layout (subsampling.py dw_striding branch): conv.0/pw…\nresolved against the checkpoint key list at runtime; any schema fork fails\nLOUDLY in main() (no silent index).\n"""\nfrom __future__ import annotations\n\nimport os\nimport sys\nimport time\nfrom pathlib import Path\n\n\ndef locate_harness() -> Path:\n    roots = [Path("/kaggle/input"), Path("/kaggle/working")]\n    for root in roots:\n        if not root.exists():\n            continue\n        for candidate in root.rglob("diar_harness.py"):\n            return candidate.parent\n    raise RuntimeError("diar_harness.py not found")\n\n\nHARNESS_DIR = locate_harness()\nsys.path.insert(0, str(HARNESS_DIR))\n\nimport diar_harness as h  # noqa: E402\n\nOUT = Path("/kaggle/working")\n\n\ndef find_ckpt() -> Path | None:\n    # Runner shares the resolved/downloaded ckpt via env (see\n    # m2_stage2_run._ensure_ckpt); fall back to dataset/working scan when\n    # a gate runs standalone (local mechanics never reach here).\n    env = os.environ.get("M2_STAGE2_CKPT")\n    if env and Path(env).exists():\n        return Path(env)\n    hits = sorted(Path("/kaggle/input").rglob("*.nemo"))\n    if not hits:\n        hits = sorted(Path("/kaggle/working").rglob("*.nemo"))\n    return hits[0] if hits else None\nREPORT: dict[str, object] = {\n    "schema_version": 1,\n    "scope": "pure_speaker_diarization",\n    "job": "m2_stage2_k3_preencode",\n}\n\n\ndef ool(x):\n    return (x + 2 - 3) // 2 + 1\n\n\ndef conv2d(x, w, b, ci, hi, wi, co):\n    # Nested-list facade over the numpy stage (kept for the mechanics\n    # transcription test, which calls THIS name). x: [ci][H][W] nested,\n    # w: [co][ci][3][3] nested. Stride 2, pad 1, floor, +ReLU (baked, as in\n    # the torch dw_striding conv0 and the C++ conv2d_relu(relu=true)).\n    import numpy as _np\n    xa = _np.asarray(x, dtype=_np.float64).reshape(ci, hi, wi)\n    wa = _np.asarray(w, dtype=_np.float64).reshape(co, ci, 3, 3)\n    xp = _np.pad(xa, ((0, 0), (1, 1), (1, 1)))\n    ho, wo = (hi + 2 - 3) // 2 + 1, (wi + 2 - 3) // 2 + 1\n    cols = _np.stack([xp[:, h:h + 2 * ho:2][:, :, ww:ww + 2 * wo:2]\n                      for h in range(3) for ww in range(3)], axis=1)\n    y = (wa.reshape(co, -1) @ cols.reshape(ci * 9, -1)) \\\n        .reshape(co, ho, wo) + _np.asarray(b, dtype=_np.float64)[:, None, None]\n    return _np.maximum(y, 0.0).tolist()\n\n\ndef dw(x, w, b, c, hi, wi):\n    # Nested-list facade, grouped DW (NO relu — matches torch dw_striding\n    # depthwise stages and C++ conv2d_dw_relu(relu=false)).\n    import numpy as _np\n    xa = _np.asarray(x, dtype=_np.float64).reshape(c, hi, wi)\n    wa = _np.asarray(w, dtype=_np.float64).reshape(c, 3, 3)\n    xp = _np.pad(xa, ((0, 0), (1, 1), (1, 1)))\n    ho, wo = (hi + 2 - 3) // 2 + 1, (wi + 2 - 3) // 2 + 1\n    cols = _np.stack([xp[:, h:h + 2 * ho:2][:, :, ww:ww + 2 * wo:2]\n                      for h in range(3) for ww in range(3)], axis=1)\n    # cols: [C, 9, ho, wo]; w is [C,3,3] here; reshape taps kh-outer to [C,9]\n    # to match the stack order (h outer, ww inner) — "ck" over the raw 3D\n    # array would throw (fixed 2026-09-17, caught by static audit).\n    y = _np.einsum("ck,ckhw->chw", wa.reshape(c, 9), cols)\n    return (y + _np.asarray(b, dtype=_np.float64)[:, None, None]).tolist()\n\n\ndef pw(x, w, b, c):\n    # Nested-list facade, pointwise +ReLU (baked).\n    import numpy as _np\n    xa = _np.asarray(x, dtype=_np.float64)\n    y = _np.asarray(w, dtype=_np.float64) @ xa + _np.asarray(b, dtype=_np.float64)[:, None]\n    return _np.maximum(y, 0.0).tolist()\n\n\ndef flat_cf(x, c, t, f):\n    # x[C][T][F] -> rows[T][C*F] (torch reshape(b,t,-1) of (b,c,t,f).T(1,2)).\n    return [[x[cc][t][ff] for cc in range(c) for ff in range(f)] for t in range(t)]\n\n\ndef lin(x, w, b):\n    # Nested-list facade, Linear [out,in] (NO transpose) + bias, no act.\n    import numpy as _np\n    y = _np.asarray(x, dtype=_np.float64) @ _np.asarray(w, dtype=_np.float64).T\n    if b is not None:\n        y = y + _np.asarray(b, dtype=_np.float64)[None, :]\n    return y.tolist()\n\n\ndef pre_encode(mel_tf, wt, F=128, C=256, D=512):\n    # Numpy-vectorized stem (same perf rewrite as K1/K2): identical math to\n    # src/subsampling.cpp — conv0+ReLU, (DW/no-ReLU, pw+ReLU) x2, flat, out.\n    # Nested-list I/O preserved for the mechanics transcription tests.\n    # dw_striding index layout (subsampling.py dw_striding branch):\n    #   conv.0 (Conv2d 1->C) / conv.1 (ReLU) / conv.2 (DW) / conv.3 (pw) /\n    #   conv.4 (ReLU) / conv.5 (DW) / conv.6 (pw) / conv.7 (ReLU),\n    #   then pre_encode.out (Linear C*F3 -> D). Resolved against the\n    #   checkpoint key list in main(); any schema fork fails LOUDLY there.\n    import numpy as _np\n    mel = _np.asarray(mel_tf, dtype=_np.float64)  # [T, F]\n    T = mel.shape[0]\n\n    def conv_stage(x, w, b, relu):\n        # x: [Ci, H, W] (numpy), w: [Co, Ci, 3, 3]. Stride 2, pad 1, floor.\n        Ci, H, W = x.shape\n        Co = w.shape[0]\n        xp = _np.pad(x, ((0, 0), (1, 1), (1, 1)))\n        ho, wo = (H + 2 - 3) // 2 + 1, (W + 2 - 3) // 2 + 1\n        # Strided windows: xp[:, h:h+2*ho:2] picks rows h, h+2, ... (ho rows).\n        cols = _np.stack([xp[:, h:h + 2 * ho:2][:, :, ww:ww + 2 * wo:2]\n                          for h in range(3) for ww in range(3)], axis=1)\n        # cols: [Ci, 9, ho, wo] -> [Ci*9, ho*wo]; GEMM vs [Co, Ci*9].\n        y = (w.reshape(Co, -1) @ cols.reshape(Ci * 9, -1)) \\\n            .reshape(Co, ho, wo) + _np.asarray(b, dtype=_np.float64)[:, None, None]\n        return _np.maximum(y, 0.0) if relu else y\n\n    def dw_stage(x, w, b):\n        # x: [C, H, W], w: [C, 3, 3] grouped. Stride 2, pad 1, NO relu.\n        C, H, W = x.shape\n        xp = _np.pad(x, ((0, 0), (1, 1), (1, 1)))\n        ho, wo = (H + 2 - 3) // 2 + 1, (W + 2 - 3) // 2 + 1\n        cols = _np.stack([xp[:, h:h + 2 * ho:2][:, :, ww:ww + 2 * wo:2]\n                          for h in range(3) for ww in range(3)], axis=1)\n        # cols: [C, 9, ho, wo]; contract taps per channel. NOTE w arrives as\n        # [C,3,3] (kept 3D by t2c); reshape to [C,9] with kh-outer order to\n        # match the stack order (h outer, ww inner) — fixed 2026-09-17,\n        # "ck" over a 3D array would throw.\n        y = _np.einsum("ck,ckhw->chw", _np.asarray(w, dtype=_np.float64).reshape(C, 9), cols)\n        return y + _np.asarray(b, dtype=_np.float64)[:, None, None]\n\n    def pw_stage(x, w, b):\n        # x: [C, HW] flattened tap grid; w: [C, C]. +ReLU (baked).\n        y = _np.asarray(w, dtype=_np.float64) @ x \\\n            + _np.asarray(b, dtype=_np.float64)[:, None]\n        return _np.maximum(y, 0.0)\n\n    c0_w = _np.asarray(wt["c0_w"], dtype=_np.float64)  # [C,1,3,3]\n    # Channel-first input [1, T, F] (mel rows = time, cols = freq).\n    xc = mel[None, :, :]  # [1, T, F]\n    s0 = conv_stage(xc, c0_w, wt["c0_b"], True)  # [C, T1, F1]\n    C_ = s0.shape[0]\n    d1 = dw_stage(s0, _np.asarray(wt["dw1_w"], dtype=_np.float64), wt["dw1_b"])\n    t2_, f2_ = d1.shape[1], d1.shape[2]\n    s1 = pw_stage(d1.reshape(C_, -1), _np.asarray(wt["pw1_w"], dtype=_np.float64),\n                  wt["pw1_b"]).reshape(C_, t2_, f2_)\n    d2 = dw_stage(s1, _np.asarray(wt["dw2_w"], dtype=_np.float64), wt["dw2_b"])\n    t3, f3 = d2.shape[1], d2.shape[2]\n    s2 = pw_stage(d2.reshape(C_, -1), _np.asarray(wt["pw2_w"], dtype=_np.float64),\n                  wt["pw2_b"]).reshape(C_, t3, f3)\n    flat = s2.transpose(1, 0, 2).reshape(t3, -1)  # torch (b,t,c*f)\n    out = flat @ _np.asarray(wt["out_w"], dtype=_np.float64).T \\\n        + _np.asarray(wt["out_b"], dtype=_np.float64)[None, :]\n    return out.tolist()\n\n\ndef t2c(w):\n    # Conv2d weight [out,in,kH,kW] -> nested [o][i][kh][kw] (NO transpose).\n    import numpy as _np\n    return _np.asarray(w.detach().cpu().numpy() if hasattr(w, "detach") else w,\n                       dtype=_np.float64).tolist()\n\n\ndef t2(w):\n    # Linear weight [out,in] -> nested [o][i] (NO transpose; same fix as K1).\n    import numpy as _np\n    return _np.asarray(w.detach().cpu().numpy() if hasattr(w, "detach") else w,\n                       dtype=_np.float64).tolist()\n\n\ndef v1(w):\n    import numpy as _np\n    return _np.asarray(w.detach().cpu().numpy() if hasattr(w, "detach") else w,\n                       dtype=_np.float64).ravel().tolist()\n\n\ndef main() -> int:\n    import numpy as _np\n    import json\n    REPORT["environment"] = h.environment_record()\n    REPORT["gpu_before"] = h.gpu_snapshot()\n    ref_hits = sorted(Path("/kaggle/input").rglob("m2_ref_short.npz")) or \\\n        sorted(Path("/kaggle/working").rglob("m2_ref_short.npz"))\n    ckpts = sorted(Path("/kaggle/input").rglob("*.nemo")) or \\\n        sorted(Path("/kaggle/working").rglob("*.nemo"))\n    env_ckpt = os.environ.get("M2_STAGE2_CKPT")\n    if env_ckpt and Path(env_ckpt).exists():\n        ckpts = [Path(env_ckpt)]\n    if not ref_hits or not ckpts:\n        REPORT["verdict"] = "ref-or-ckpt-missing"\n        REPORT["finished_utc"] = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())\n        h.emit_report(REPORT, name="m2_stage2_k3_verdict.json")\n        return 0\n    import tarfile, io\n    import torch\n    with tarfile.open(str(ckpts[0]), "r") as tf:\n        for m in tf.getmembers():\n            if m.name.endswith(".ckpt"):\n                f = tf.extractfile(m)\n                obj = torch.load(io.BytesIO(f.read()), map_location="cpu", weights_only=False)\n                sd = obj.get("state_dict", obj)\n                break\n    keys = sorted([k for k in sd if "pre_encode" in k])\n    REPORT["pre_encode_keys"] = keys\n    ref_dir = ref_hits[0].parent\n    REPORT["ref_dir"] = str(ref_dir)\n    REPORT["ckpt"] = str(ckpts[0])\n    # Resolve dw_striding index layout against the checkpoint (loud on fork).\n    p = "encoder.pre_encode."\n    wt = {"c0_w": t2c(sd[p + "conv.0.weight"]), "c0_b": v1(sd[p + "conv.0.bias"]),\n          "dw1_w": t2c(sd[p + "conv.2.weight"]), "dw1_b": v1(sd[p + "conv.2.bias"]),\n          "pw1_w": t2(sd[p + "conv.3.weight"]), "pw1_b": v1(sd[p + "conv.3.bias"]),\n          "dw2_w": t2c(sd[p + "conv.5.weight"]), "dw2_b": v1(sd[p + "conv.5.bias"]),\n          "pw2_w": t2(sd[p + "conv.6.weight"]), "pw2_b": v1(sd[p + "conv.6.bias"]),\n          "out_w": t2(sd[p + "out.weight"]), "out_b": v1(sd[p + "out.bias"])}\n    # pw 1x1 weights are [C,C,1,1] -> squeeze to [C,C] for the pw() helper.\n    for k in ("pw1_w", "pw2_w"):\n        w = wt[k]\n        if isinstance(w[0][0], list):\n            wt[k] = [[v[0][0] if isinstance(v[0], list) else v[0] for v in row] for row in w]\n    # DW weights are [C,1,3,3] -> squeeze dim-1 to [C,3,3] for the dw() helper\n    # (fixed 2026-09-17: t2c keeps [o][i][kh][kw]; groups=C means i==0 only).\n    for k in ("dw1_w", "dw2_w"):\n        w = wt[k]\n        if isinstance(w[0][0], list) and len(w[0]) == 1:\n            wt[k] = [ch[0] for ch in w]\n    # c0_w is [C,1,3,3] and conv2d() indexes w[o][i][kh][kw] with ci==1:\n    # w[o][0][kh][kw] resolves correctly, no squeeze needed.\n    per_audio = {}\n    for label in ("short", "mid"):\n        zpath = ref_dir / f"m2_ref_{label}.npz"\n        if not zpath.exists():\n            continue\n        z = _np.load(str(zpath), allow_pickle=True)\n        chunks = sorted(set(k.split("/")[0] for k in z.files if k.startswith("chunk")))\n        gates = []\n        for chunk in chunks:\n            mel = z[chunk + "/mel_window"].tolist()  # [T_mel, 128]\n            got = pre_encode(mel, wt)\n            ref = z[chunk + "/pre_encode"].tolist()\n            import math as _m\n            r = _np.asarray(ref, dtype=_np.float64)\n            g = _np.asarray(got, dtype=_np.float64)\n            gates.append({"chunk": chunk,\n                          "max_abs": float(_np.abs(r - g).max()),\n                          "mean_abs": float(_np.abs(r - g).mean()),\n                          "cosine": float((r * g).sum() / (_m.sqrt((r * r).sum() * (g * g).sum()) + 1e-12)),\n                          "T": len(ref)})\n        per_audio[label] = gates\n    REPORT["gates"] = per_audio\n    REPORT["worst_max_abs"] = max((m["max_abs"] for gates in per_audio.values() for m in gates),\n                                  default=float("nan"))\n    REPORT["verdict"] = "k3-measured"\n    REPORT["note"] = ("pre_encode teacher-forced fp32-vs-fp32 spreads; "\n                      "pin gate thresholds from these numbers per plan §1.")\n    REPORT["finished_utc"] = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())\n    h.emit_report(REPORT, name="m2_stage2_k3_verdict.json")\n    print(json.dumps({k: v for k, v in REPORT.items() if k != "gates"}, indent=1)[:2000])\n    return 0\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'

