def _materialize(name: str, blob: str) -> Path:
    # Kaggle mounts /kaggle/src read-only: never write next to the runner.
    # Sibling files (local dev) still win; embedded copies land in WORK.
    sib = HERE / name
    if sib.exists():
        return sib
    path = WORK / name
    if path.exists():
        return path
    if not blob:
        raise RuntimeError(
            f"{name} missing: no sibling file and no embedded copy "
            "(run embed_stage2.py before push)")
    WORK.mkdir(parents=True, exist_ok=True)
    path.write_text(blob, encoding="utf-8")
    return path


def _ensure_ckpt() -> Path:
    # The .nemo checkpoint (471MB) is NOT in any dataset: it rode along in
    # /kaggle/working only for the Stage 0 session that downloaded it.
    # Re-download from HF at runtime (same curl as Stage 0 S0-c; internet
    # is enabled on this kernel). Cached under WORK for sibling re-runs.
    import subprocess
    ckpts = sorted(Path("/kaggle/input").rglob("*.nemo"))
    if not ckpts:
        ckpts = sorted(Path("/kaggle/working").rglob("*.nemo"))
    if ckpts:
        return ckpts[0]
    dest = WORK / NEMO_FILE
    if dest.exists() and dest.stat().st_size > 100_000_000:
        return dest
    WORK.mkdir(parents=True, exist_ok=True)
    url = f"https://huggingface.co/{HF_REPO}/resolve/main/{NEMO_FILE}?download=true"
    print(f"[stage2] downloading .nemo ({NEMO_FILE}) ...", flush=True)
    p = subprocess.run(
        ["curl", "-L", "--fail", "--retry", "3", "--silent", "--show-error",
         "-o", str(dest), url],
        capture_output=True, text=True, timeout=3600)
    if p.returncode != 0 or not dest.exists():
        raise RuntimeError(f"nemo-ckpt-download-failed rc={p.returncode}: {(p.stderr or p.stdout)[-500:]}")
    if dest.stat().st_size < 100_000_000:
        raise RuntimeError(f"nemo-ckpt-truncated: {dest.stat().st_size} bytes")
    print(f"[stage2] ckpt ready: {dest.stat().st_size} bytes", flush=True)
    return dest


def main() -> int:
    t0 = time.time()
    results = {}
    try:
        ckpt = _ensure_ckpt()
    except RuntimeError as exc:
        print(f"[stage2] {exc}", flush=True)
        return 0
    import os
    os.environ["M2_STAGE2_CKPT"] = str(ckpt)
    for gate in ("m2_stage2_k1.py", "m2_stage2_k2.py", "m2_stage2_k3.py"):
        blob = dict(EMBEDDED)[gate]
        try:
            path = _materialize(gate, blob)
        except RuntimeError as exc:
            results[gate] = f"missing: {exc}"
            continue
        print(f"[stage2] running {gate}", flush=True)
        try:
            import runpy
            runpy.run_path(str(path), run_name="__main__")
            results[gate] = "ran"
        except SystemExit as exc:
            results[gate] = f"exit-{exc.code}"
        except BaseException as exc:  # noqa: BLE001 — gate bugs must not kill siblings
            results[gate] = f"error: {exc!r}"
    print(f"[stage2] done in {time.time() - t0:.0f}s: {results}", flush=True)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
